function repeatStr(s, n){ var o=''; for(var i=0;i<n;i++) o+=s; return o; }
function fillLines(text, opts){
  opts=opts||{}; var width=opts.width!=null?opts.width:12;
  var ch=opts.char!=null?opts.char:' ';
  var side=opts.side||'end';
  var lines=String(text||'').split(/\r?\n/);
  var out=[];
  for(var i=0;i<lines.length;i++){
    var L=lines[i];
    if(opts.trim) L=L.replace(/^\s+|\s+$/g,'');
    if(L.length>=width){ out.push(L); continue; }
    var pad=width-L.length;
    if(side==='start') out.push(repeatStr(ch,pad)+L);
    else if(side==='both'){ var l=Math.floor(pad/2), r=pad-l; out.push(repeatStr(ch,l)+L+repeatStr(ch,r)); }
    else out.push(L+repeatStr(ch,pad));
  }
  return {ok:true, text:out.join('\n'), lines:out.length};
}

var EXPORTS={fillLines:fillLines,repeatStr:repeatStr};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FillForgePure = EXPORTS; }
